-- One-time: the DO-GRIP and TANG-GRIP code keys get the Parting catalog's
-- chipformer data (pp. 4-7): each chipformer row's details (description, rake
-- and clearance, feed f ~ W / factor, suitable materials) where it has none,
-- the chipformers they lack, and the chipformer selection and feed tables
-- (TANG-GRIP also its ETG clamping keys) unless a table of that title exists.

-- Rows of a section (by key): details filled where empty, missing rows added.
CREATE FUNCTION "_ck_chip"(v jsonb, skey text, det jsonb, add jsonb) RETURNS jsonb AS $f$
  SELECT jsonb_set(v, '{sections}', (
    SELECT jsonb_agg(CASE WHEN s ->> 'key' = skey THEN jsonb_set(s, '{rows}', (
      SELECT COALESCE(jsonb_agg(CASE WHEN coalesce(x ->> 'details', '') = '' AND det ? (x ->> 'code') THEN x || jsonb_build_object('details', det ->> (x ->> 'code')) ELSE x END ORDER BY i), '[]'::jsonb)
      FROM jsonb_array_elements(s -> 'rows') WITH ORDINALITY AS t(x, i)
    ) || COALESCE((
      SELECT jsonb_agg(n || CASE WHEN det ? (n ->> 'code') THEN jsonb_build_object('details', det ->> (n ->> 'code')) ELSE '{}'::jsonb END)
      FROM jsonb_array_elements(add) n
      WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(s -> 'rows') x WHERE x ->> 'code' = n ->> 'code')
    ), '[]'::jsonb)) ELSE s END ORDER BY o)
    FROM jsonb_array_elements(v -> 'sections') WITH ORDINALITY AS u(s, o)))
$f$ LANGUAGE sql;

-- Tables added unless one of the same title exists.
CREATE FUNCTION "_ck_tables"(v jsonb, add jsonb) RETURNS jsonb AS $f$
  SELECT v || jsonb_build_object('tables', COALESCE(v -> 'tables', '[]'::jsonb) || COALESCE((
    SELECT jsonb_agg(t) FROM jsonb_array_elements(add) t
    WHERE NOT EXISTS (SELECT 1 FROM jsonb_array_elements(COALESCE(v -> 'tables', '[]'::jsonb)) x WHERE x ->> 'title' = t ->> 'title')
  ), '[]'::jsonb))
$f$ LANGUAGE sql;

UPDATE "AppSetting" a
SET "value" = "_ck_tables"("_ck_chip"(a."value"::jsonb, 'dg-chip', $ck${"C": "First choice for parting bars, hard materials and tough applications. Positive rake, single cavity with negative land and shoulders for extra edge strength. Medium-to-high feed. ~12° rake, 7° clearance. Feed f ≈ W insert / 18 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel (first choice), High temp. alloys, Nonferrous, Cast iron; not for austenitic stainless. High temp. alloys and nonferrous with IC20 only.", "MF": "Double-sided parting and grooving insert for soft and hard materials, medium feed. 12° rake. Feed f ≈ W insert / 21 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys (first choice), Cast iron; not for nonferrous. Austenitic stainless: medium to high feed.", "JT": "Based on J with a T-land reinforced frontal cutting edge: between C and J; compact chips, higher feeds than J. 5° rake, 7° clearance. Feed f ≈ W insert / 24 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys, Cast iron; not for nonferrous.", "J": "First choice for soft materials, parting tubes, small diameters and thin-walled parts. Positive rake; low-to-medium feed. 4° rake, 7° clearance. Feed f ≈ W insert / 26 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys, Nonferrous; not for cast iron.", "Z": "High positive rake for parting tubes, thin walls and small diameters; soft materials, bearing steel and stainless steel; low-to-medium feeds. 11° rake, 7° clearance. Feed f ≈ W insert / 28 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys, Nonferrous; not for cast iron.", "LF": "Double-sided parting and grooving insert for stainless steel. 0° rake, 7° clearance. Feed f ≈ W insert / 31 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys; not for nonferrous, cast iron.", "LFT": "LF with a T-land (stainless steel). Materials: Alloy steel, Austenitic stainless (first choice), High temp. alloys; not for nonferrous, cast iron.", "UA": "For low feeds on CrNi alloys and low carbon steel (bearing industry and similar problematic materials); narrow chipformer for short chips. ~12° rake, 7° clearance. Feed f ≈ W insert / 40 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel (first choice); not for austenitic stainless, high temp. alloys, nonferrous, cast iron. UT is slightly tighter than UA.", "UT": "For low feeds on CrNi alloys and low carbon steel; slightly tighter than UA. ~12° rake, 7° clearance. Feed f ≈ W insert / 40 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel (first choice); not for austenitic stainless, high temp. alloys, nonferrous, cast iron.", "P": "Very positive rake and sharp edge for soft materials, slim parts and general parting. 13° rake, 7° clearance. Feed f ≈ W insert / 55 mm/rev (neutral inserts; R/L: reduce by 20-40%). Materials: Alloy steel (first choice), Austenitic stainless, Nonferrous; not for high temp. alloys, cast iron.", "W": "Central ridged chipformer for hard materials and interrupted cuts. Materials: Alloy steel (first choice), Cast iron; not for austenitic stainless, high temp. alloys, nonferrous."}$ck$::jsonb, $ck$[{"code": "JT", "meaning": "J with a T-land reinforced edge – between C and J"}, {"code": "C-jet", "meaning": "C type with coolant (JETCUT) – first choice for high temp. alloys"}]$ck$::jsonb), $ck$[{"title": "Chipformer selection for workpiece materials (Parting catalog) – ★ first choice, ✓ suitable, ✗ not recommended", "columns": ["Chipformer", "Alloy steel", "Austenitic stainless", "High temp. alloys", "Nonferrous", "Cast iron"], "rows": [["C", "★", "✗", "✓", "✓", "✓"], ["W", "★", "✗", "✗", "✗", "✓"], ["MF", "✓", "★", "★", "✗", "✓"], ["JT", "✓", "★", "✓", "✗", "✓"], ["J", "✓", "★", "✓", "✓", "✗"], ["Z", "✓", "★", "✓", "✓", "✗"], ["LFT", "✓", "★", "✓", "✗", "✗"], ["LF", "✓", "★", "✓", "✗", "✗"], ["UT", "★", "✗", "✗", "✗", "✗"], ["P", "★", "✓", "✗", "✓", "✗"], ["A", "✗", "✗", "✗", "★", "✗"], ["C-jet (coolant)", "✓", "✓", "★", "✗", "✗"]]}, {"title": "Recommended feed by chipformer: f ≈ W insert / factor [mm/rev] (neutral inserts; R/L: reduce by 20-40%)", "columns": ["Chipformer", "Factor", "Rake / clearance", "Typical feed range (mm/rev, approx.)"], "rows": [["C", "18", "~12° rake, 7° clearance", "0.13-0.25"], ["MF", "21", "12° rake", "0.07-0.20"], ["M", "22", "~12° rake, 7° clearance", ""], ["JT", "24", "5° rake, 7° clearance", ""], ["J", "26", "4° rake, 7° clearance", "0.05-0.11"], ["Z", "28", "11° rake, 7° clearance", ""], ["LF", "31", "0° rake, 7° clearance", "0.06-0.09"], ["UA", "40", "~12° rake, 7° clearance", ""], ["UT", "40", "~12° rake, 7° clearance", "0.03-0.07"], ["A", "43", "9° rake, 7° clearance", ""], ["P", "55", "13° rake, 7° clearance", ""]]}]$ck$::jsonb)::text
WHERE a."key" = 'codekey.dogrip';
UPDATE "AppSetting" a
